-- Verification
SELECT t.name AS tenant_name,
       COUNT(DISTINCT td.id) AS source_databases,
       COUNT(DISTINCT dt.id) AS metadata_tables
FROM tenants AS t
LEFT JOIN tenant_databases AS td ON td.tenant_id = t.id
LEFT JOIN database_tables AS dt ON dt.tenant_id = t.id
WHERE t.slug IN ('tenant-a', 'tenant-b', 'tenant-c')
GROUP BY t.id, t.name
ORDER BY t.name;

SELECT email, full_name, status
FROM users
WHERE email IN ('tenant-a@example.test', 'tenant-a-analyst@example.test', 'tenant-b@example.test', 'tenant-c@example.test')
ORDER BY email;
